/** SCR-53–58: local-first health UI. Storage mirrors the domain boundary. */
const STORAGE_KEY = 'beefcare-ui-demo'
const readDemo = <T,>(key: string, fallback: T): T => {
  if (typeof window === 'undefined') return fallback
  try { const root = JSON.parse(window.localStorage.getItem(STORAGE_KEY) || '{}'); return (root.account?.[key] as T) ?? fallback } catch { return fallback }
}
const writeDemo = (key: string, value: unknown) => {
  if (typeof window === 'undefined') return
  try { const root = JSON.parse(window.localStorage.getItem(STORAGE_KEY) || '{}'); window.localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...root, account: { ...(root.account || {}), [key]: value } })) } catch { /* best effort demo storage */ }
}
type Severity = 'MILD' | 'MODERATE' | 'SEVERE'
type CaseStatus = 'OPEN' | 'CHRONIC' | 'CLOSED'
type Outcome = 'RECOVERED' | 'DIED' | 'MISSING'
type RecordKind = 'OPEN' | 'FOLLOW_UP' | 'TREATMENT' | 'STATUS' | 'CORRECTION' | 'VOID'
type Attachment = { name: string; size?: number; addedAt: string }
type HealthCase = {
  id: string; code: string; cattleCode: string; cattleName?: string; breed?: string; sex?: string; age?: string; pen: string
  diagnosis?: string; signs: string; severity: Severity; status: CaseStatus; openedAt: string; chronicSince?: string
  closedAt?: string; outcome?: Outcome; contagious: boolean; linkedVaccination?: string; version: number
}
type HealthRecord = {
  id: string; caseId: string; kind: RecordKind; status: 'VALID' | 'VOIDED'; at: string; by: string; version: number
  signs?: string; temperature?: number; progress?: 'IMPROVED' | 'UNCHANGED' | 'WORSENED'; diagnosis?: string
  medicine?: string; dose?: string; route?: string; courseDays?: number; withdrawalDays?: number; withdrawalUntil?: string
  performedBy?: string; advice?: string; cost?: number; attachments?: Attachment[]; reason?: string; revisionOf?: string; confirmedBy?: string
}
type AuditEntry = { id: string; at: string; actor: string; action: string; targetId: string; reason?: string; version: number }
type CattleContext = { code: string; name: string; breed: string; sex: string; age: string; pen: string }
const dateOnly = (value: string) => value.slice(0, 10)
const nowLocal = () => { const d = new Date(); const offset = d.getTimezoneOffset(); return new Date(d.getTime() - offset * 60_000).toISOString().slice(0, 16) }
const addDays = (value: string, days: number) => { const d = new Date(value); d.setDate(d.getDate() + days); return d.toISOString().slice(0, 10) }
const formatDate = (value?: string) => value ? new Intl.DateTimeFormat('vi-VN', { dateStyle: 'medium', timeStyle: value.length > 10 ? 'short' : undefined }).format(new Date(value)) : '—'
const severityLabel: Record<Severity, string> = { MILD: 'Nhẹ', MODERATE: 'Trung bình', SEVERE: 'Nặng' }
const statusLabel: Record<CaseStatus, string> = { OPEN: 'Đang mở', CHRONIC: 'Theo dõi mạn tính', CLOSED: 'Đã đóng' }
const recordStatusLabel = (status: HealthRecord['status'], corrected = false) => status === 'VOIDED' ? 'Đã hủy' : corrected ? 'Đã chỉnh sửa' : 'Hợp lệ'
const actorLabel = (value: string) => value.replace(/ · Manager$/, ' · Quản lý')
const routeLabel: Record<string, string> = { INTRAMUSCULAR: 'Tiêm bắp', SUBCUTANEOUS: 'Tiêm dưới da', INTRAVENOUS: 'Tiêm tĩnh mạch', ORAL: 'Uống', TOPICAL: 'Bôi ngoài da', OTHER: 'Khác' }
const progressLabel: Record<string, string> = { IMPROVED: 'Cải thiện', UNCHANGED: 'Không đổi', WORSENED: 'Xấu đi' }
const recordKindLabel: Record<RecordKind, string> = { OPEN: 'Mở ca', FOLLOW_UP: 'Theo dõi', TREATMENT: 'Điều trị', STATUS: 'Trạng thái', CORRECTION: 'Chỉnh sửa', VOID: 'Hủy bản ghi' }
const outcomeLabel: Record<Outcome, string> = { RECOVERED: 'Đã khỏi', DIED: 'Đã chết', MISSING: 'Mất tích' }
const toneForSeverity = (value: Severity) => value === 'SEVERE' ? 'err' : value === 'MODERATE' ? 'warn' : 'ok'
const activeMembers = () => readDemo<Array<{ name?: string; email?: string; status?: string }>>('members', accountMembers).filter((m) => !m.status || m.status === 'ACTIVE' || m.status === 'Đang hoạt động').map((m) => m.name || m.email || '').filter(Boolean)
const activeMedicines = () => (loadCatalogueItems('medicines') as MedicineItem[]).filter((item) => item.status === 'ACTIVE')
const medicineByName = (name: string) => activeMedicines().find((item) => item.name === name)
const seedCases = (): HealthCase[] => [
  { id: 'case-125', code: 'HC-0125', cattleCode: 'BC-000125', cattleName: 'Bò cái 125', breed: 'Lai Sind', sex: 'Cái', age: '26 tháng', pen: 'A1 · Khu theo dõi', diagnosis: 'Viêm móng', signs: 'Đi khập khiễng, giảm ăn', severity: 'MODERATE', status: 'OPEN', openedAt: '2026-10-20T09:00', contagious: false, version: 1 },
  { id: 'case-240', code: 'HC-0240', cattleCode: 'BC-000240', cattleName: 'Bò 240', breed: 'Zebu đỏ', sex: 'Đực', age: '31 tháng', pen: 'A2 · Khu cách ly', diagnosis: 'Sốt nhẹ sau tiêm', signs: 'Nhiệt độ tăng nhẹ sau tiêm', severity: 'MILD', status: 'CLOSED', openedAt: '2026-10-05T08:30', closedAt: '2026-10-08T16:00', outcome: 'RECOVERED', contagious: false, version: 2 },
]
const seedRecords = (): HealthRecord[] => [
  { id: 'record-open-125', caseId: 'case-125', kind: 'OPEN', status: 'VALID', at: '2026-10-20T09:00', by: 'Nguyễn Lan · Manager', version: 1, signs: 'Đi khập khiễng, giảm ăn', temperature: 39.1, diagnosis: 'Viêm móng' },
  { id: 'record-open-240', caseId: 'case-240', kind: 'OPEN', status: 'VALID', at: '2026-10-05T08:30', by: 'Nguyễn Lan · Manager', version: 1, signs: 'Nhiệt độ tăng nhẹ sau tiêm', temperature: 39.5, diagnosis: 'Sốt nhẹ sau tiêm' },
  { id: 'record-close-240', caseId: 'case-240', kind: 'STATUS', status: 'VALID', at: '2026-10-08T16:00', by: 'Nguyễn Lan · Manager', version: 2, progress: 'IMPROVED', reason: 'Đã hồi phục, ăn uống bình thường' },
]
const isCaseStatus = (value: unknown): value is CaseStatus => value === 'OPEN' || value === 'CHRONIC' || value === 'CLOSED'
const isSeverity = (value: unknown): value is Severity => value === 'MILD' || value === 'MODERATE' || value === 'SEVERE'
const normaliseCase = (value: unknown): HealthCase | undefined => {
  if (!value || typeof value !== 'object') return undefined
  const row = value as Record<string, unknown>
  const id = String(row.id || '')
  const cattleCode = String(row.cattleCode || row.cattle || '')
  if (!id || !cattleCode) return undefined
  const status = isCaseStatus(row.status) ? row.status : undefined
  const openedAt = String(row.openedAt || row.opened || '')
  if (!status || !openedAt) return undefined
  const severity = isSeverity(row.severity) ? row.severity : row.severity === 'MEDIUM' ? 'MODERATE' : undefined
  if (!severity) return undefined
  return {
    id, code: String(row.code || row.caseCode || id), cattleCode, cattleName: row.cattleName ? String(row.cattleName) : undefined,
    breed: row.breed ? String(row.breed) : undefined, sex: row.sex ? String(row.sex) : undefined, age: row.age ? String(row.age) : undefined,
    pen: String(row.pen || '—'), diagnosis: row.diagnosis ? String(row.diagnosis) : row.title ? String(row.title) : undefined,
    signs: String(row.signs || row.note || row.description || 'Chưa có mô tả'), severity, status, openedAt,
    chronicSince: row.chronicSince ? String(row.chronicSince) : undefined, closedAt: row.closedAt ? String(row.closedAt) : undefined,
    outcome: row.outcome === 'RECOVERED' || row.outcome === 'DIED' || row.outcome === 'MISSING' ? row.outcome : undefined,
    contagious: Boolean(row.contagious), linkedVaccination: row.linkedVaccination ? String(row.linkedVaccination) : undefined,
    version: Number.isFinite(Number(row.version)) && Number(row.version) > 0 ? Number(row.version) : 1,
  }
}
const normaliseRecord = (value: unknown): HealthRecord | undefined => {
  if (!value || typeof value !== 'object') return undefined
  const row = value as Record<string, unknown>
  const id = String(row.id || '')
  const caseId = String(row.caseId || row.healthCaseId || '')
  const kind = row.kind as RecordKind
  const at = String(row.at || row.occurredAt || '')
  if (!id || !caseId || !at || !['OPEN', 'FOLLOW_UP', 'TREATMENT', 'STATUS', 'CORRECTION', 'VOID'].includes(kind)) return undefined
  return { ...row, id, caseId, kind, at, by: String(row.by || row.recordedBy || 'Không rõ'), status: row.status === 'VOIDED' ? 'VOIDED' : 'VALID', version: Number(row.version) || 1 } as HealthRecord
}
const ensureHealthStressData = () => {
  const config = loadLocalStressConfig()
  if (!config.enabled || typeof window === 'undefined' || readDemo('health-stress-seeded', false)) return
  const rawCases = readDemo<unknown>('health-cases-preview', null)
  const rawRecords = readDemo<unknown>('health-records-preview', readDemo<unknown>('health-events-preview', null))
  const cases = (Array.isArray(rawCases) ? rawCases.map(normaliseCase).filter((row): row is HealthCase => Boolean(row)) : seedCases())
  const records = (Array.isArray(rawRecords) ? rawRecords.map(normaliseRecord).filter((row): row is HealthRecord => Boolean(row)) : seedRecords())
  const audits = readDemo<AuditEntry[]>('health-audit-preview', [])
  const cattle = expandLocalTable('health-cattle', readDemo<CowSeed[]>('cattle-preview', initialCows))
  const severities: Severity[] = ['MILD', 'MODERATE', 'SEVERE']
  const statuses: CaseStatus[] = ['OPEN', 'CHRONIC', 'CLOSED']
  const diagnoses = ['Viêm móng', 'Rối loạn tiêu hóa', 'Theo dõi hô hấp', 'Sốt nhẹ', 'Giảm ăn']
  for (let index = cases.length; index < config.rowsPerTable; index += 1) {
    const cow = cattle[index % cattle.length]
    const status = statuses[index % statuses.length]
    const openedAt = new Date(Date.UTC(2026, 8, 1) + index * 8 * 3_600_000).toISOString().slice(0, 16)
    const id = `case-stress-${String(index + 1).padStart(4, '0')}`
    cases.push({
      id,
      code: `HC-${String(index + 301).padStart(4, '0')}`,
      cattleCode: cow.code,
      cattleName: cow.name?.trim() || `Bò ${cow.code}`,
      breed: cow.breed,
      sex: cow.sex,
      age: cow.ageLong || cow.ageShort,
      pen: cow.barn,
      diagnosis: diagnoses[index % diagnoses.length],
      signs: `${['Đi khập khiễng', 'Ăn giảm', 'Ho nhẹ', 'Nhiệt độ tăng', 'Cần theo dõi thêm'][index % 5]} · ca mô phỏng ${index + 1}`,
      severity: severities[index % severities.length],
      status,
      openedAt,
      chronicSince: status === 'CHRONIC' ? openedAt.slice(0, 10) : undefined,
      closedAt: status === 'CLOSED' ? new Date(new Date(openedAt).getTime() + 3 * 86_400_000).toISOString().slice(0, 16) : undefined,
      outcome: status === 'CLOSED' ? 'RECOVERED' : undefined,
      contagious: index % 11 === 0,
      version: status === 'CLOSED' ? 2 : 1,
    })
  }
  for (const item of cases) {
    if (records.some((record) => record.caseId === item.id)) continue
    records.push({ id: `record-open-${item.id}`, caseId: item.id, kind: 'OPEN', status: 'VALID', at: item.openedAt, by: 'Nguyễn Lan · Manager', version: 1, signs: item.signs, diagnosis: item.diagnosis, temperature: 38.5 + (records.length % 6) / 10 })
  }
  for (let index = audits.length; index < config.rowsPerTable; index += 1) {
    const item = cases[index % cases.length]
    audits.push({ id: `audit-health-${String(index + 1).padStart(4, '0')}`, at: item.openedAt, actor: 'Nguyễn Lan · Manager', action: 'OPEN_CASE', targetId: item.id, version: item.version })
  }
  writeDemo('health-cases-preview', cases)
  writeDemo('health-records-preview', records)
  writeDemo('health-events-preview', records)
  writeDemo('health-audit-preview', audits)
  writeDemo('health-stress-seeded', true)
}
const getCases = (): HealthCase[] => {
  ensureHealthStressData()
  const raw = readDemo<unknown>('health-cases-preview', null)
  if (raw == null) return seedCases()
  const values = Array.isArray(raw) ? raw : []
  const migrated = values.map(normaliseCase).filter((row): row is HealthCase => Boolean(row))
  if (!values.length || migrated.length !== values.length) { const fallback = seedCases(); writeDemo('health-cases-preview', fallback); return fallback }
  return migrated
}
const getRecords = (): HealthRecord[] => {
  ensureHealthStressData()
  const raw = readDemo<unknown>('health-records-preview', readDemo<unknown>('health-events-preview', null))
  if (raw == null) return seedRecords()
  const values = Array.isArray(raw) ? raw : []
  const migrated = values.map(normaliseRecord).filter((row): row is HealthRecord => Boolean(row))
  if (migrated.length !== values.length) { writeDemo('health-records-preview', seedRecords()); writeDemo('health-events-preview', seedRecords()); return seedRecords() }
  return migrated
}
const getAudits = () => { ensureHealthStressData(); return readDemo<AuditEntry[]>('health-audit-preview', []) }
const saveCollections = (cases: HealthCase[], records: HealthRecord[], audits: AuditEntry[]) => {
  writeDemo('health-cases-preview', cases); writeDemo('health-records-preview', records); writeDemo('health-events-preview', records); writeDemo('health-audit-preview', audits)
  const incidents = cases.filter((item) => item.status === 'CLOSED' && (item.outcome === 'DIED' || item.outcome === 'MISSING'))
  const markers = incidents.map((item) => ({ id: `health-exit-${item.id}`, caseId: item.id, cattleCode: item.cattleCode, type: item.outcome === 'DIED' ? 'DEATH' : 'MISSING', status: 'PENDING', locked: true, source: item.code }))
  writeDemo('health-pending-exits', markers)
  const vouchers = readDemo<Array<Record<string, unknown>>>('herd-exit-vouchers', [])
  const nextVouchers = [...vouchers]
  for (const marker of markers) if (!nextVouchers.some((row) => row.healthCaseId === marker.caseId)) nextVouchers.unshift({ id: marker.id, healthCaseId: marker.caseId, type: marker.type, date: dateOnly(cases.find((item) => item.id === marker.caseId)?.closedAt || nowLocal()), status: 'PENDING', lines: [{ code: marker.cattleCode, weight: '', price: '' }], source: 'Health case', locked: true })
  writeDemo('herd-exit-vouchers', nextVouchers)
  const cattle = readDemo<CowSeed[]>('cattle-preview', initialCows)
  if (markers.length) writeDemo('cattle-preview', cattle.map((cow) => markers.some((marker) => marker.cattleCode === cow.code) ? { ...cow, status: 'EXIT_PENDING' } : cow))
}
function cattleContext(code: string, item?: HealthCase): CattleContext { const row = readDemo<Array<Record<string, unknown>>>('cattle-preview', []).find((candidate) => candidate.code === code); return { code, name: String(row?.name || item?.cattleName || 'Chưa đặt tên'), breed: String(row?.breed || item?.breed || 'Lai Sind'), sex: String(row?.sex || item?.sex || 'Cái'), age: String(row?.ageLong || row?.ageShort || item?.age || '26 tháng'), pen: String(row?.barn || item?.pen || 'A1 · Khu theo dõi') } }
function selectedCase(caseId?: string, cattleCode?: string) { const all = getCases(); const selected = readDemo<{ id?: string; code?: string }>('selected-health-case', {}); if (caseId) return all.find((item) => item.id === caseId); if (cattleCode) return all.find((item) => item.cattleCode === cattleCode); if (selected.id) return all.find((item) => item.id === selected.id); return selected.code ? all.find((item) => item.cattleCode === selected.code) : undefined }
function selectedCattle(code?: string): CowSeed | undefined { const rows = readDemo<CowSeed[]>('cattle-preview', initialCows); const selected = readDemo<{ code?: string }>('selected-cattle', {}); return rows.find((row) => row.code === (code || selected.code)) }
function isActiveCattle(code: string) { const cattle = selectedCattle(code); return Boolean(cattle && cattle.status === 'ACTIVE') }
function selectCase(item: HealthCase) { writeDemo('selected-health-case', { id: item.id, code: item.cattleCode }); writeDemo('selected-cattle', { code: item.cattleCode }) }
function Shell({ screen, children, actions }: { screen: ScreenDefinition; children: ReactNode; actions?: ReactNode }) { return <div className="flex w-full min-w-0 flex-col gap-6"><PageHeader title={screen.viTitle} sub="Theo dõi ca bệnh, điều trị và lịch tái khám của đàn." badge={<span className="text-xs font-semibold text-subtle">Quản lý trang trại</span>}>{actions}</PageHeader>{children}</div> }
function StateBoundary({ state, title, children }: { state: ReviewState; title: string; children: ReactNode }) { if (state === 'loading') return <LoadingState label={`Đang tải ${title.toLowerCase()}…`} rows={5} />; if (state === 'error') return <InlineMessage tone="err" title="Không thể tải dữ liệu.">Dữ liệu chưa sẵn sàng. Hãy thử lại khi kết nối ổn định.</InlineMessage>; return <>{children}</> }
function CattleStrip({ item }: { item: HealthCase }) { const cattle = cattleContext(item.cattleCode, item); return <div className="border-y border-rule py-3 text-xs"><strong className="text-ink">{cattle.code}</strong><span className="ml-2 text-subtle">{cattle.name} · {cattle.breed} · {cattle.sex} · {cattle.age} · Chuồng {cattle.pen}</span></div> }
function roleCanEdit(role?: ScreenRole, state?: ReviewState) { return role === 'manager' && state !== 'read-only' }

function CaseList({ screen, role, state }: { screen: ScreenDefinition; role?: ScreenRole; state: ReviewState }) {
  const navigate = useNavigate(); const all = getCases(); const [query, setQuery] = useState(''); const [tab, setTab] = useState<'ALL' | CaseStatus>('OPEN'); const [severity, setSeverity] = useState('ALL'); const [pen, setPen] = useState('ALL'); const [from, setFrom] = useState(''); const [to, setTo] = useState('')
  if (state === 'empty') return <Shell screen={screen} actions={roleCanEdit(role, state) && <Button variant="primary" onClick={() => navigate('/ui/scr-55')}>+ Mở ca sức khỏe</Button>}><EmptyState title="Chưa có ca sức khỏe" description="Chưa có ca bệnh hợp lệ trong trang trại hiện tại. Chọn một bò đang nuôi để mở ca." actionLabel={roleCanEdit(role, state) ? 'Mở ca sức khỏe' : undefined} onAction={roleCanEdit(role, state) ? () => navigate('/ui/scr-55') : undefined} /></Shell>
  const visible = useMemo(() => all.filter((item) => (tab === 'ALL' || item.status === tab) && (severity === 'ALL' || item.severity === severity) && (pen === 'ALL' || item.pen === pen) && (!from || dateOnly(item.openedAt) >= from) && (!to || dateOnly(item.openedAt) <= to) && `${item.code} ${item.cattleCode} ${item.cattleName || ''} ${item.diagnosis || ''} ${item.signs}`.toLowerCase().includes(query.toLowerCase().trim())).sort((a, b) => b.openedAt.localeCompare(a.openedAt)), [all, from, pen, query, severity, tab, to])
  return <Shell screen={screen} actions={roleCanEdit(role, state) && <Button variant="primary" onClick={() => navigate('/ui/scr-55')}>+ Mở ca sức khỏe</Button>}><StateBoundary state={state} title="ca sức khỏe"><SummaryStrip items={[{ label: 'Đang mở', value: all.filter((x) => x.status === 'OPEN').length }, { label: 'Mạn tính', value: all.filter((x) => x.status === 'CHRONIC').length }, { label: 'Đã đóng', value: all.filter((x) => x.status === 'CLOSED').length }, { label: 'Hiển thị', value: visible.length }]} />{!roleCanEdit(role, state) && <InlineMessage tone="info">Bạn đang xem ca sức khỏe. Quản lý có thể mở ca, ghi tái khám, điều trị và cập nhật trạng thái; bạn vẫn mở được toàn bộ hồ sơ.</InlineMessage>}<nav aria-label="Trạng thái ca" className="flex flex-wrap gap-2 border-b border-rule pb-3">{[['OPEN', 'Đang mở'], ['CHRONIC', 'Mạn tính'], ['CLOSED', 'Đã đóng'], ['ALL', 'Tất cả']].map(([value, label]) => <Button key={value} small variant={tab === value ? 'primary' : 'default'} onClick={() => setTab(value as typeof tab)}>{label} ({value === 'ALL' ? all.length : all.filter((x) => x.status === value).length})</Button>)}</nav><FilterBar><input className={`${inputCls} min-w-64 flex-1`} value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Mã ca, mã bò, chẩn đoán hoặc dấu hiệu…" aria-label="Tìm ca sức khỏe" /><select className={`${inputCls} w-40`} value={severity} onChange={(e) => setSeverity(e.target.value)} aria-label="Mức độ"><option value="ALL">Mức độ: tất cả</option><option value="MILD">Nhẹ</option><option value="MODERATE">Trung bình</option><option value="SEVERE">Nặng</option></select><select className={`${inputCls} w-48`} value={pen} onChange={(e) => setPen(e.target.value)} aria-label="Chuồng"><option value="ALL">Chuồng: tất cả</option>{Array.from(new Set(all.map((x) => x.pen))).map((value) => <option key={value}>{value}</option>)}</select><input className={`${inputCls} w-40`} type="date" value={from} onChange={(e) => setFrom(e.target.value)} aria-label="Mở từ" /><input className={`${inputCls} w-40`} type="date" value={to} onChange={(e) => setTo(e.target.value)} aria-label="Mở đến" /></FilterBar>{visible.length ? <Table wide scroll><thead><tr><Th>Ca · bò</Th><Th>Chuồng</Th><Th>Chẩn đoán · dấu hiệu</Th><Th>Mức độ</Th><Th>Mở lúc</Th><Th>Trạng thái</Th><Th /></tr></thead><tbody>{visible.map((item) => { const canFollowUp = roleCanEdit(role, state) && !item.id.startsWith('case-stress-') && item.status !== 'CLOSED'; return <tr key={item.id}><Td><button className="font-semibold text-brand hover:underline" onClick={() => { selectCase(item); navigate(`/ui/scr-54?code=${encodeURIComponent(item.cattleCode)}`) }}>{item.code}<span className="block font-normal text-subtle">{item.cattleCode} · {item.cattleName}</span></button></Td><Td>{item.pen}</Td><Td><span>{item.diagnosis || item.signs}</span>{item.contagious && <Badge className="ml-2" tone="err">Nghi lây nhiễm · cách ly</Badge>}<span className="mt-1 block text-[11px] text-subtle">{item.signs}</span></Td><Td><Badge tone={toneForSeverity(item.severity)}>{severityLabel[item.severity]}</Badge></Td><Td>{formatDate(item.openedAt)}</Td><Td><Badge tone={item.status === 'CLOSED' ? 'outline' : item.status === 'CHRONIC' ? 'warn' : 'ok'}>{item.status === 'CLOSED' && item.outcome ? outcomeLabel[item.outcome] : statusLabel[item.status]}</Badge></Td><Td><div className="flex flex-wrap gap-2">{roleCanEdit(role, state) && <Button small disabled={!canFollowUp} title={canFollowUp ? undefined : 'Dữ liệu thử hoặc ca đã đóng chỉ có thể xem'} onClick={() => { selectCase(item); navigate(`/ui/scr-56?caseId=${encodeURIComponent(item.id)}`) }}>Ghi tái khám</Button>}<Button small onClick={() => { selectCase(item); navigate(`/ui/scr-54?code=${encodeURIComponent(item.cattleCode)}`) }}>Mở hồ sơ</Button></div></Td></tr> })}</tbody></Table> : <EmptyState title="Không có ca phù hợp" description="Thử bỏ bớt bộ lọc hoặc mở một ca sức khỏe mới." actionLabel={roleCanEdit(role, state) ? 'Mở ca sức khỏe' : undefined} onAction={roleCanEdit(role, state) ? () => navigate('/ui/scr-55') : undefined} />}<Info items={[["Quyền", role === 'manager' ? (state === 'read-only' ? 'Quản lý · chỉ đọc' : 'Quản lý · được ghi nhận') : 'Thành viên · chỉ xem'], ['Khoảng thời gian', 'Ngày mở ca · mặc định 30 ngày với ca mới nhất'], ['Nguồn dữ liệu', 'Dữ liệu hồ sơ sức khỏe']]} /></StateBoundary></Shell>
}
function effectiveRecords(records: HealthRecord[]) { const superseded = new Set(records.filter((record) => record.revisionOf && (record.kind === 'CORRECTION' || record.kind === 'VOID')).map((record) => record.revisionOf as string)); return records.filter((record) => record.status === 'VALID' && !superseded.has(record.id) && record.kind !== 'VOID') }
function latestRecord(records: HealthRecord[]) { return [...effectiveRecords(records)].sort((a, b) => a.at.localeCompare(b.at) || a.id.localeCompare(b.id)).at(-1) }
function healthStateFor(item: HealthCase, records: HealthRecord[]) { const allCases = getCases(); const latest = latestRecord(records.filter((record) => allCases.some((row) => row.cattleCode === item.cattleCode && row.id === record.caseId))); if (!latest) return 'Khỏe mạnh'; if (latest.kind === 'TREATMENT') return 'Đang điều trị'; if (latest.kind === 'STATUS' && latest.reason === 'Đã khỏi') return 'Khỏe mạnh'; const related = allCases.find((row) => row.id === latest.caseId); return related?.status === 'CLOSED' ? (related.outcome === 'DIED' ? 'Đã chết' : related.outcome === 'MISSING' ? 'Mất tích' : 'Khỏe mạnh') : 'Theo dõi' }
function withdrawalFor(items: HealthCase[], records: HealthRecord[]) {
  const caseIds = new Set(items.map((item) => item.id)); const treatmentDates = effectiveRecords(records).filter((record) => record.kind === 'TREATMENT' && record.withdrawalUntil && caseIds.has(record.caseId)).map((record) => record.withdrawalUntil as string)
  const vaccinations = readDemo<Array<Record<string, unknown>>>('vaccination-preview', []); const supersededVaccinations = new Set(vaccinations.filter((row) => row.revisionOf).map((row) => String(row.revisionOf))); const vaccinationDates = vaccinations.filter((row) => row.status === 'ADMINISTERED' && (row.recordStatus || 'VALID') === 'VALID' && !supersededVaccinations.has(String(row.id)) && row.source === 'ON_FARM' && row.withdrawal && items.some((item) => item.cattleCode === row.code)).map((row) => String(row.withdrawal))
  return [...treatmentDates, ...vaccinationDates].sort().at(-1) || '—'
}

function Profile({ screen, role, state }: { screen: ScreenDefinition; role?: ScreenRole; state: ReviewState }) {
  const navigate = useNavigate(); const [params] = useSearchParams(); const item = selectedCase(params.get('caseId') || undefined, params.get('cattleCode') || params.get('code') || undefined); const [refresh, setRefresh] = useState(0); const [voidTarget, setVoidTarget] = useState<HealthRecord>(); const [voidReason, setVoidReason] = useState(''); const [voidError, setVoidError] = useState(''); void refresh; const all = getCases(); const records = getRecords(); const audits = getAudits(); const editable = roleCanEdit(role, state)
  if (!item) return <Shell screen={screen}><EmptyState title="Chưa có hồ sơ sức khỏe" description="Chọn một ca trong danh sách hoặc mở tab sức khỏe từ hồ sơ bò." actionLabel="Về danh sách" onAction={() => navigate('/ui/scr-53')} /></Shell>
  const cattleCases = all.filter((row) => row.cattleCode === item.cattleCode); const supersededIds = new Set(records.filter((row) => row.revisionOf && (row.kind === 'CORRECTION' || row.kind === 'VOID')).map((row) => row.revisionOf as string)); const caseRecords = records.filter((row) => row.caseId === item.id).map((row) => supersededIds.has(row.id) ? { ...row, status: 'VOIDED' as const } : row).sort((a, b) => a.at.localeCompare(b.at) || a.id.localeCompare(b.id)); const validRecords = effectiveRecords(records.filter((row) => row.caseId === item.id)); const attachmentCount = caseRecords.reduce((total, row) => total + (row.attachments?.length || 0), 0); const caseAudit = audits.filter((entry) => entry.targetId === item.id || caseRecords.some((row) => row.id === entry.targetId))
  const mutateVoid = (record?: HealthRecord) => { if (!editable) return; setVoidTarget(record); setVoidReason(''); setVoidError('') }
  const confirmVoid = () => { if (!editable || !voidTarget) return; const reason = voidReason.trim(); if (!reason) { setVoidError('Lý do hủy bản ghi là bắt buộc.'); return } const freshCase = getCases().find((row) => row.id === item.id); const freshRecord = getRecords().find((row) => row.id === voidTarget.id); if (!freshCase || freshCase.version !== item.version || !freshRecord || freshRecord.version !== voidTarget.version) { setVoidError('Hồ sơ đã thay đổi. Hãy tải lại trước khi hủy bản ghi.'); return } const next: HealthRecord = { id: `record-${Date.now()}`, caseId: item.id, kind: 'VOID', status: 'VOIDED', at: nowLocal(), by: 'Nguyễn Lan · Manager', version: freshCase.version + 1, revisionOf: voidTarget.id, reason }; const audit: AuditEntry = { id: `audit-${Date.now()}`, at: next.at, actor: next.by, action: 'VOID_RECORD', targetId: voidTarget.id, reason, version: freshCase.version + 1 }; saveCollections(all.map((row) => row.id === item.id ? { ...row, version: row.version + 1 } : row), [...records, next], [...audits, audit]); setVoidTarget(undefined); setVoidReason(''); setVoidError(''); setRefresh((value) => value + 1) }
  const openEdit = (record: HealthRecord) => { if (!editable) return; writeDemo('selected-health-record', record); navigate(record.kind === 'TREATMENT' ? '/ui/scr-57' : record.kind === 'OPEN' ? '/ui/scr-55' : '/ui/scr-56') }
  return <Shell screen={screen} actions={<><Button small onClick={() => navigate('/ui/scr-53')}>← Danh sách ca</Button>{editable && <><Button small onClick={() => { selectCase(item); navigate(`/ui/scr-55?code=${encodeURIComponent(item.cattleCode)}`) }}>Mở / bổ sung ca</Button><Button small onClick={() => navigate('/ui/scr-56')}>Theo dõi</Button><Button small onClick={() => navigate('/ui/scr-57')}>Điều trị</Button><Button variant="primary" onClick={() => navigate('/ui/scr-58')}>Cập nhật / đóng</Button></>}</>}><StateBoundary state={state} title="hồ sơ sức khỏe"><CattleStrip item={item} /><WorkSection title="Tóm tắt sức khỏe" description="Ngữ cảnh bò và trạng thái được tính từ các bản ghi hợp lệ."><SummaryStrip items={[{ label: 'Trạng thái bò', value: healthStateFor(item, records) }, { label: 'Ca hiện tại', value: statusLabel[item.status] }, { label: 'Ngừng thuốc đến', value: withdrawalFor(cattleCases, records), note: withdrawalFor(cattleCases, records) !== '—' ? 'Không được xuất bán trước ngày này' : undefined }, { label: 'Phiên bản hồ sơ', value: `v${item.version}`, note: 'Bản ghi cũ không bị ghi đè' }]} /><Info items={[["Mã ca", item.code], ["Dấu hiệu chính", item.signs], ["Chẩn đoán nghi ngờ", item.diagnosis || 'Chưa nhập · hệ thống không tự chẩn đoán'], ["Mức độ", severityLabel[item.severity]], ["Nghi lây nhiễm", item.contagious ? 'Có · cần cách ly' : 'Không'], ["Mở lúc", formatDate(item.openedAt)], ["Đóng lúc", formatDate(item.closedAt)], ["Kết quả", item.outcome ? outcomeLabel[item.outcome] : '—']]}/></WorkSection><WorkSection title="Ca đang theo dõi"><div className="grid min-w-0 gap-4 lg:grid-cols-2">{cattleCases.filter((row) => row.status !== 'CLOSED').map((row) => <Card key={row.id} title={<span>{row.code} · {row.diagnosis || row.signs}</span>} sub={`${statusLabel[row.status]} · mở ${formatDate(row.openedAt)}`} actions={editable && <Button small onClick={() => { selectCase(row); navigate('/ui/scr-58') }}>Cập nhật</Button>}><Info cols={2} items={[["Mức độ", severityLabel[row.severity]], ["Điều trị", records.filter((record) => record.caseId === row.id && record.kind === 'TREATMENT' && record.status === 'VALID').length], ["Chuồng", row.pen], ["Ca", row.contagious ? 'Nghi lây nhiễm' : 'Không đánh dấu lây nhiễm']]}/></Card>)}</div>{!cattleCases.some((row) => row.status !== 'CLOSED') && <EmptyState compact title="Không có ca đang mở hoặc theo dõi mạn tính" description="Hồ sơ đang ở trạng thái khỏe mạnh theo các bản ghi hợp lệ." />}</WorkSection><WorkSection title="Diễn tiến và điều trị" description="Các bản ghi cũ luôn được giữ; mỗi lần sửa hoặc hủy tạo một phiên bản lịch sử mới."><Table wide scroll><thead><tr><Th>Thời điểm</Th><Th>Loại</Th><Th>Chi tiết</Th><Th>Người ghi</Th><Th>Phiên bản</Th>{editable && <Th>Thao tác</Th>}</tr></thead><tbody>{caseRecords.map((record) => { const isVoided = record.status === 'VOIDED' || caseRecords.some((row) => row.kind === 'VOID' && row.revisionOf === record.id); const detail = record.kind === 'TREATMENT' ? `${record.medicine} · ${record.dose} · ${routeLabel[record.route || ''] || record.route || '—'} · ${record.courseDays || 1} ngày · ngừng thuốc ${record.withdrawalUntil || '—'}` : record.kind === 'FOLLOW_UP' ? `${progressLabel[record.progress || ''] || record.progress || '—'} · ${record.signs || '—'}${record.temperature ? ` · ${record.temperature}°C` : ''}` : record.signs || record.reason || (record.kind === 'STATUS' ? 'Cập nhật trạng thái' : record.diagnosis || 'Mở ca'); return <tr key={record.id} className={isVoided ? 'text-faint line-through' : undefined}><Td>{formatDate(record.at)}</Td><Td>{recordKindLabel[record.kind]}<span className="ml-2 no-underline"><Badge tone={isVoided ? 'err' : record.revisionOf ? 'info' : 'ok'}>{recordStatusLabel(isVoided ? 'VOIDED' : record.status, Boolean(record.revisionOf))}</Badge></span></Td><Td>{detail}<span className="mt-1 block text-[11px] no-underline text-subtle">{record.cost ? `Chi phí ${record.cost.toLocaleString('vi-VN')} đ · ` : ''}{record.attachments?.length ? `${record.attachments.length} tệp đính kèm` : ''}</span></Td><Td>{actorLabel(record.by)}</Td><Td>v{record.version}</Td>{editable && <Td><Button small onClick={() => openEdit(record)} disabled={isVoided || record.kind === 'VOID'}>Sửa</Button><Button small onClick={() => mutateVoid(record)} disabled={isVoided || record.kind === 'VOID'}>Hủy</Button></Td>}</tr> })}{!caseRecords.length && <tr><Td colSpan={editable ? 6 : 5}>Chưa có diễn tiến.</Td></tr>}</tbody></Table><div className="mt-3 flex flex-wrap gap-3 text-xs text-subtle"><span>{attachmentCount} tệp đính kèm</span><span>{caseAudit.length} thay đổi đã lưu</span><span>Phiên bản hồ sơ v{item.version}</span></div></WorkSection><WorkSection title="Ca trước đây của bò"><Table><thead><tr><Th>Mã ca</Th><Th>Dấu hiệu / chẩn đoán</Th><Th>Trạng thái</Th><Th>Kết quả · tháng</Th></tr></thead><tbody>{cattleCases.filter((row) => row.id !== item.id && row.status === 'CLOSED').map((row) => <tr key={row.id}><Td>{row.code}</Td><Td>{row.diagnosis || row.signs}</Td><Td>{statusLabel[row.status]}</Td><Td>{row.outcome ? outcomeLabel[row.outcome] : '—'} · {row.closedAt ? formatDate(row.closedAt) : '—'}</Td></tr>)}</tbody></Table></WorkSection></StateBoundary><ActionDialog open={Boolean(voidTarget)} title="Hủy bản ghi sức khỏe" description="Nhập lý do để lưu lịch sử thay đổi. Bản ghi cũ vẫn được giữ nguyên." error={voidError} confirmLabel="Xác nhận hủy" confirmTone="danger" onCancel={() => { setVoidTarget(undefined); setVoidError('') }} onConfirm={confirmVoid}><Field label="Lý do hủy bản ghi *"><textarea autoFocus className={`${inputCls} min-h-24`} maxLength={500} value={voidReason} onChange={(event) => { setVoidReason(event.target.value); setVoidError('') }} placeholder="Ví dụ: ghi nhầm hoặc trùng bản ghi." /></Field></ActionDialog></Shell>
}

type FormKind = 'OPEN' | 'FOLLOW_UP' | 'TREATMENT' | 'STATUS'
function RecordForm({ screen, role, state, kind }: { screen: ScreenDefinition; role?: ScreenRole; state: ReviewState; kind: FormKind }) {
  const navigate = useNavigate(); const [params] = useSearchParams(); const existingItem = selectedCase(params.get('caseId') || undefined, params.get('cattleCode') || params.get('code') || undefined); const selectedCow = selectedCattle(params.get('cattleCode') || params.get('code') || undefined); const item = existingItem || (kind === 'OPEN' && selectedCow ? { id: '__new__', code: 'Mới', cattleCode: selectedCow.code, cattleName: selectedCow.name, breed: selectedCow.breed, sex: selectedCow.sex, age: selectedCow.ageLong || selectedCow.ageShort, pen: selectedCow.barn, signs: '', severity: 'MODERATE' as Severity, status: 'OPEN' as CaseStatus, openedAt: nowLocal(), contagious: false, version: 0 } : undefined); const editing = readDemo<HealthRecord | null>('selected-health-record', null); const manager = roleCanEdit(role, state); const members = activeMembers(); const current = editing && editing.caseId === item?.id && editing.kind === kind ? editing : undefined
  const [at, setAt] = useState(current?.at?.slice(0, 16) || nowLocal()); const [temperature, setTemperature] = useState(current?.temperature?.toString() || ''); const [signs, setSigns] = useState(current?.signs || ''); const [diagnosis, setDiagnosis] = useState(current?.diagnosis || item?.diagnosis || ''); const [severity, setSeverity] = useState<Severity>(item?.severity || 'MODERATE'); const [contagious, setContagious] = useState(Boolean(item?.contagious)); const [progress, setProgress] = useState<'IMPROVED' | 'UNCHANGED' | 'WORSENED'>(current?.progress || 'IMPROVED'); const [observer, setObserver] = useState(current?.by?.split(' · ')[0] || members[0] || 'Nguyễn Lan'); const [recordMode, setRecordMode] = useState<'NEW' | 'EXISTING'>('NEW'); const [existingId, setExistingId] = useState(item?.id || ''); const [medicine, setMedicine] = useState(current?.medicine || activeMedicines()[0]?.name || ''); const [dose, setDose] = useState(current?.dose || activeMedicines()[0]?.referenceDose || ''); const [route, setRoute] = useState(current?.route || activeMedicines()[0]?.route || 'INTRAMUSCULAR'); const [courseDays, setCourseDays] = useState(String(current?.courseDays || 1)); const [withdrawalDays, setWithdrawalDays] = useState(String(current?.withdrawalDays ?? activeMedicines()[0]?.withdrawalDays ?? 0)); const [performedBy, setPerformedBy] = useState(current?.performedBy || members[0] || 'Nguyễn Lan'); const [advice, setAdvice] = useState(current?.advice || ''); const [cost, setCost] = useState(current?.cost?.toString() || ''); const [attachments, setAttachments] = useState<Attachment[]>(current?.attachments || []); const [status, setStatus] = useState<CaseStatus>(item?.status || 'OPEN'); const [outcome, setOutcome] = useState<Outcome | ''>(item?.outcome || ''); const [confirmedBy, setConfirmedBy] = useState(members[0] || 'Nguyễn Lan'); const [reason, setReason] = useState(''); const [error, setError] = useState('')
  if (!item || state === 'empty') return <Shell screen={screen}><EmptyState title="Chưa có ca để ghi nhận" description="Hãy chọn một ca trong danh sách sức khỏe trước." actionLabel="Về danh sách" onAction={() => navigate('/ui/scr-53')} /></Shell>
  if (state === 'loading') return <LoadingState label="Đang tải biểu mẫu…" />
  if (!manager) return <Shell screen={screen}><InlineMessage tone="warn" title="Chỉ Quản lý được ghi nhận.">Vai trò hiện tại hoặc chế độ xem chỉ đọc không cho phép thay đổi. Dữ liệu không bị sửa.</InlineMessage></Shell>
  const saveRecord = (event: FormEvent) => {
    event.preventDefault(); setError(''); const date = new Date(at); const now = new Date(); const temp = temperature ? Number(temperature) : undefined; const numericCost = cost ? Number(cost) : undefined; const all = getCases(); const records = getRecords(); const audits = getAudits(); const target = (all.find((row) => row.id === item.id) || item) as HealthCase
    if (kind === 'OPEN' && !isActiveCattle(item.cattleCode)) return setError('Chỉ bò đang nuôi mới được mở hoặc bổ sung ca sức khỏe. Bò đang chờ xuất, đã xuất hoặc đã hủy bị khóa.')
    if (kind !== 'OPEN' && (!all.some((row) => row.id === target.id) || (target.status !== 'OPEN' && target.status !== 'CHRONIC'))) return setError('Ca đã đóng hoặc không còn hợp lệ; không thể ghi thêm diễn tiến.')
    if (current) { const latest = records.find((record) => record.id === current.id); if (!latest || latest.version !== current.version || target?.version !== item.version) return setError('Bản ghi đã thay đổi. Hãy tải lại hồ sơ trước khi sửa.') }
    if (!at || Number.isNaN(date.getTime()) || date > now) return setError('Thời điểm không được để trống hoặc ở tương lai.')
    if (temp != null && (temp < 35 || temp > 43)) return setError('Nhiệt độ phải trong khoảng 35,0–43,0°C.')
    if (kind === 'OPEN' && !signs.trim()) return setError('Dấu hiệu / mô tả là bắt buộc.')
    if (kind === 'OPEN' && signs.length > 1000) return setError('Dấu hiệu / mô tả tối đa 1.000 ký tự.')
    if (kind === 'OPEN' && diagnosis.length > 100) return setError('Chẩn đoán nghi ngờ tối đa 100 ký tự.')
    if ((kind === 'FOLLOW_UP' || kind === 'TREATMENT' || kind === 'STATUS') && date < new Date(target.openedAt)) return setError('Thời điểm không được trước thời điểm mở ca.')
    if (kind === 'FOLLOW_UP' && !signs.trim()) return setError('Mô tả diễn tiến là bắt buộc.')
    if (kind === 'STATUS' && !signs.trim()) return setError('Cập nhật / đóng ca phải có diễn tiến mới nhất.')
    const course = Number(courseDays); const withdrawal = Number(withdrawalDays)
    const medicineItem = medicineByName(medicine)
    if (kind === 'TREATMENT' && (!medicineItem || medicineItem.status !== 'ACTIVE' || !dose.trim() || dose.length > 50 || !route || !course || course < 1 || course > 30 || withdrawal < 0 || withdrawal > 365 || !performedBy.trim())) return setError('Thuốc phải đang được sử dụng trong danh mục; kiểm tra liều, đường dùng, liệu trình 1–30 ngày, ngừng thuốc 0–365 ngày và người thực hiện.')
    if (kind === 'STATUS' && status === 'CLOSED' && (!outcome || !confirmedBy.trim() || !members.includes(confirmedBy.trim()))) return setError('Khi đóng ca cần kết quả và người xác nhận là thành viên đang hoạt động của trại.')
    const withdrawalUntil = kind === 'TREATMENT' ? addDays(dateOnly(at), course - 1 + withdrawal) : undefined
    const record: HealthRecord = { id: `record-${Date.now()}`, caseId: item.id, kind, status: 'VALID', at, by: `${kind === 'TREATMENT' ? performedBy : observer} · Manager`, version: item.version + 1, signs: signs.trim() || undefined, temperature: temp, diagnosis: diagnosis.trim() || undefined, progress: kind === 'FOLLOW_UP' || kind === 'STATUS' ? progress : undefined, medicine: kind === 'TREATMENT' ? medicine : undefined, dose: kind === 'TREATMENT' ? dose.trim() : undefined, route: kind === 'TREATMENT' ? route : undefined, courseDays: kind === 'TREATMENT' ? course : undefined, withdrawalDays: kind === 'TREATMENT' ? withdrawal : undefined, withdrawalUntil, performedBy: kind === 'TREATMENT' ? performedBy : undefined, advice: kind === 'TREATMENT' ? advice.trim() || undefined : undefined, cost: numericCost, attachments, reason: kind === 'STATUS' ? (status === 'CLOSED' ? outcomeLabel[outcome as Outcome] : 'Cập nhật trạng thái') : undefined }
    const wasEditing = Boolean(current); if (wasEditing && !reason.trim()) return setError('Lý do sửa bản ghi là bắt buộc để tạo phiên bản lịch sử.')
    const recordWithConfirmation = kind === 'STATUS' ? { ...record, confirmedBy: confirmedBy.trim() } : record
    const finalRecord = wasEditing ? { ...recordWithConfirmation, kind: 'CORRECTION' as const, revisionOf: current!.id, reason: reason.trim() } : recordWithConfirmation
    const existing = getCases().find((row) => row.id === existingId && row.cattleCode === item.cattleCode && row.status !== 'CLOSED'); const targetCase = kind === 'OPEN' && recordMode === 'EXISTING' ? (existing || item) : item
    const updatedCase: HealthCase = kind === 'OPEN' && recordMode === 'NEW' && !current ? { id: `case-${Date.now()}`, code: `HC-${String(Date.now()).slice(-4)}`, cattleCode: item.cattleCode, cattleName: item.cattleName, breed: item.breed, sex: item.sex, age: item.age, pen: item.pen, diagnosis: diagnosis.trim() || undefined, signs: signs.trim(), severity, status: 'OPEN', openedAt: at, contagious, linkedVaccination: item.linkedVaccination, version: 1 } : { ...targetCase, diagnosis: diagnosis.trim() || targetCase.diagnosis, signs: signs.trim() || targetCase.signs, contagious, status: kind === 'STATUS' ? status : kind === 'TREATMENT' && targetCase.status === 'CHRONIC' ? 'OPEN' : targetCase.status, chronicSince: kind === 'STATUS' && status === 'CHRONIC' ? (targetCase.chronicSince || dateOnly(at)) : status === 'OPEN' || kind === 'TREATMENT' ? undefined : targetCase.chronicSince, closedAt: kind === 'STATUS' && status === 'CLOSED' ? at : kind === 'STATUS' && status !== 'CLOSED' ? undefined : targetCase.closedAt, outcome: kind === 'STATUS' && status === 'CLOSED' ? outcome as Outcome : kind === 'STATUS' && status !== 'CLOSED' ? undefined : targetCase.outcome, version: targetCase.version + 1 }
    const caseList = getCases().some((row) => row.id === updatedCase.id) ? getCases().map((row) => row.id === updatedCase.id ? updatedCase : row) : [updatedCase, ...getCases()]; const linkedRecord = { ...finalRecord, caseId: updatedCase.id }; const audit: AuditEntry = { id: `audit-${Date.now()}`, at: nowLocal(), actor: linkedRecord.by, action: wasEditing ? 'CORRECT_RECORD' : kind === 'STATUS' ? 'UPDATE_CASE' : `ADD_${kind}`, targetId: wasEditing ? current!.id : updatedCase.id, reason: wasEditing ? reason.trim() : undefined, version: updatedCase.version }; saveCollections(caseList, [...getRecords(), linkedRecord], [...getAudits(), audit]); writeDemo('selected-health-record', null); selectCase(updatedCase); navigate(`/ui/scr-54?code=${encodeURIComponent(updatedCase.cattleCode)}`)
  }
  const addFiles = (files: File[]) => setAttachments((currentFiles) => [...currentFiles, ...files.map((file) => ({ name: file.name, size: file.size, addedAt: nowLocal() }))]); const back = () => navigate(`/ui/scr-54?code=${encodeURIComponent(item.cattleCode)}`)
  const commonAttachments = <WorkSection title="Chi phí và tệp đính kèm" description="Tệp đính kèm lưu cùng hồ sơ; dữ liệu gốc không bị ghi đè."><div className="grid gap-4 sm:grid-cols-2"><Field label="Chi phí (đ) · tuỳ chọn"><input className={inputCls} type="number" min="0" value={cost} onChange={(e) => setCost(e.target.value)} /></Field><div><Dropzone hint="PDF, JPG/PNG · lưu tên tệp cùng hồ sơ" onFiles={addFiles} /><div className="mt-2"><Docs docs={attachments.map((file) => ({ name: file.name, ext: file.name.split('.').at(-1)?.toUpperCase() || 'FILE' }))} onRemove={(index) => setAttachments((files) => files.filter((_, i) => i !== index))} /></div></div></div></WorkSection>
  return <Shell screen={screen}><StateBoundary state={state} title="biểu mẫu"><form onSubmit={saveRecord} className="min-w-0"><div className="space-y-5"><CattleStrip item={item} />{current && <Note tone="info">Đang sửa bản ghi {formatDate(current.at)}. Bản ghi cũ giữ nguyên; Lưu sẽ tạo phiên bản mới trong lịch sử.</Note>}{kind === 'TREATMENT' && item.status === 'CHRONIC' && <Note tone="warn">Ca mạn tính: ghi điều trị sẽ đưa ca trở lại trạng thái đang mở và trạng thái bò thành Đang điều trị.</Note>}<WorkSection title={kind === 'OPEN' ? 'Ghi bất thường và mở ca' : kind === 'FOLLOW_UP' ? 'Ghi theo dõi ca sức khỏe' : kind === 'TREATMENT' ? 'Ghi điều trị thực tế' : 'Cập nhật / đóng ca'} description="Các trường có * là bắt buộc. Thời điểm được kiểm tra theo thứ tự diễn tiến của ca.">{kind === 'OPEN' && <><Info items={[["Bò", item.cattleCode], ["Giống · giới tính · tuổi", `${item.breed || '—'} · ${item.sex || '—'} · ${item.age || '—'}`], ["Chuồng", item.pen]]}/><Field label="Ca sức khỏe *"><select className={inputCls} value={recordMode} onChange={(e) => setRecordMode(e.target.value as 'NEW' | 'EXISTING')}><option value="NEW">Mở ca mới</option><option value="EXISTING">Bổ sung vào ca đang mở / mạn tính</option></select></Field>{recordMode === 'EXISTING' && <Field label="Ca hiện có *"><select className={inputCls} value={existingId} onChange={(e) => setExistingId(e.target.value)}>{getCases().filter((row) => row.cattleCode === item.cattleCode && row.status !== 'CLOSED').map((row) => <option key={row.id} value={row.id}>{row.code} · {row.diagnosis || row.signs}</option>)}</select></Field>}</>}{kind !== 'TREATMENT' && kind !== 'STATUS' && <><Field label="Dấu hiệu / mô tả *"><textarea className={inputCls} rows={4} maxLength={1000} value={signs} onChange={(e) => setSigns(e.target.value)} /><span className="text-[11px] text-subtle">{signs.length}/1.000</span></Field><div className="grid gap-4 md:grid-cols-2"><Field label="Thời điểm quan sát *"><input className={inputCls} type="datetime-local" value={at} max={nowLocal()} onChange={(e) => setAt(e.target.value)} /></Field><Field label="Nhiệt độ (°C) · tuỳ chọn"><input className={inputCls} type="number" min="35" max="43" step="0.1" value={temperature} onChange={(e) => setTemperature(e.target.value)} placeholder="35,0–43,0" /></Field></div></>}{(kind === 'OPEN' || kind === 'STATUS') && <><div className="grid gap-4 md:grid-cols-2"><Field label="Chẩn đoán nghi ngờ · tuỳ chọn"><input className={inputCls} maxLength={100} value={diagnosis} onChange={(e) => setDiagnosis(e.target.value)} placeholder="Ví dụ: Tiêu chảy, Viêm phổi…" /></Field>{kind === 'OPEN' && <Field label="Mức độ *"><select className={inputCls} value={severity} onChange={(e) => setSeverity(e.target.value as Severity)}><option value="MILD">Nhẹ</option><option value="MODERATE">Trung bình</option><option value="SEVERE">Nặng</option></select></Field>}</div><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={contagious} onChange={(e) => setContagious(e.target.checked)} />Nghi lây nhiễm · cần cách ly</label></>}{kind === 'FOLLOW_UP' && <><div className="grid gap-4 md:grid-cols-3"><Field label="Tiến triển *"><select className={inputCls} value={progress} onChange={(e) => setProgress(e.target.value as typeof progress)}><option value="IMPROVED">Cải thiện</option><option value="UNCHANGED">Không đổi</option><option value="WORSENED">Xấu đi</option></select></Field><Field label="Người quan sát"><select className={inputCls} value={observer} onChange={(e) => setObserver(e.target.value)}>{[...new Set([observer, ...members])].map((name) => <option key={name}>{name}</option>)}</select></Field><Field label="Thời điểm quan sát *"><input className={inputCls} type="datetime-local" value={at} max={nowLocal()} onChange={(e) => setAt(e.target.value)} /></Field></div><Field label="Mô tả diễn tiến *"><textarea className={inputCls} rows={4} maxLength={1000} value={signs} onChange={(e) => setSigns(e.target.value)} /></Field></>}{kind === 'TREATMENT' && <><Info items={[["Ca", item.code], ["Bò", item.cattleCode], ["Mở ca", formatDate(item.openedAt)], ["Trạng thái hiện tại", statusLabel[item.status]]]} /><div className="grid gap-4 md:grid-cols-2"><Field label="Thuốc đang sử dụng *"><select className={inputCls} value={medicine} onChange={(e) => setMedicine(e.target.value)}><option>Oxytetracycline</option><option>Flunixin</option><option>Vitamin B complex</option></select></Field><Field label="Liều *"><input className={inputCls} maxLength={50} value={dose} onChange={(e) => setDose(e.target.value)} placeholder="30 ml/con" /></Field><Field label="Đường dùng *"><select className={inputCls} value={route} onChange={(e) => setRoute(e.target.value)}><option value="INTRAMUSCULAR">Tiêm bắp</option><option value="SUBCUTANEOUS">Tiêm dưới da</option><option value="INTRAVENOUS">Tiêm tĩnh mạch</option><option value="ORAL">Uống</option><option value="TOPICAL">Bôi ngoài da</option><option value="OTHER">Khác</option></select></Field><Field label="Lần dùng đầu tiên *"><input className={inputCls} type="datetime-local" value={at} max={nowLocal()} onChange={(e) => setAt(e.target.value)} /></Field><Field label="Liệu trình (ngày) *"><input className={inputCls} type="number" min="1" max="30" value={courseDays} onChange={(e) => setCourseDays(e.target.value)} /></Field><Field label="Ngừng thuốc (ngày) *"><input className={inputCls} type="number" min="0" max="365" value={withdrawalDays} onChange={(e) => setWithdrawalDays(e.target.value)} /></Field></div><Info items={[["Ngày ngừng thuốc dự kiến", at && courseDays && withdrawalDays ? formatDate(addDays(dateOnly(at), Number(courseDays) - 1 + Number(withdrawalDays))) : '—'], ["Gợi ý thuốc", 'Liều, đường dùng và thời gian ngừng thuốc lấy từ danh mục · có thể chỉnh'], ["Tồn kho", 'Không theo dõi tồn kho thuốc']]} /><div className="grid gap-4 md:grid-cols-2"><Field label="Người thực hiện *"><input className={inputCls} maxLength={100} value={performedBy} onChange={(e) => setPerformedBy(e.target.value)} /></Field><Field label="Tư vấn thú y · tuỳ chọn"><textarea className={inputCls} rows={2} value={advice} onChange={(e) => setAdvice(e.target.value)} /></Field></div></>}{kind === 'STATUS' && <><Info items={[["Ca", item.code], ["Bò", item.cattleCode], ["Mở lúc", formatDate(item.openedAt)], ["Trạng thái hiện tại", statusLabel[item.status]]]} /><Field label="Trạng thái ca *"><select className={inputCls} value={status} onChange={(e) => setStatus(e.target.value as CaseStatus)}>{item.status === 'OPEN' ? <><option value="OPEN">Giữ trạng thái đang mở</option><option value="CHRONIC">Chuyển sang theo dõi mạn tính</option><option value="CLOSED">Đóng ca</option></> : <><option value="CHRONIC">Giữ theo dõi mạn tính</option><option value="OPEN">Trở lại trạng thái đang mở</option><option value="CLOSED">Đóng ca</option></>}</select></Field><Field label="Tiến triển mới nhất"><textarea className={inputCls} rows={3} maxLength={1000} value={signs} onChange={(e) => setSigns(e.target.value)} placeholder="Ghi diễn tiến mới nhất…" /></Field>{status === 'CLOSED' ? <div className="grid gap-4 md:grid-cols-3"><Field label="Kết quả *"><select className={inputCls} value={outcome} onChange={(e) => setOutcome(e.target.value as Outcome)}><option value="">Chọn kết quả</option><option value="RECOVERED">Đã khỏi</option><option value="DIED">Đã chết</option><option value="MISSING">Mất tích</option></select></Field><Field label="Đóng lúc *"><input className={inputCls} type="datetime-local" value={at} max={nowLocal()} onChange={(e) => setAt(e.target.value)} /></Field><Field label="Xác nhận bởi *"><input className={inputCls} value={confirmedBy} onChange={(e) => setConfirmedBy(e.target.value)} /></Field></div> : <Field label="Cập nhật lúc *"><input className={inputCls} type="datetime-local" value={at} max={nowLocal()} onChange={(e) => setAt(e.target.value)} /></Field>}</>}</WorkSection>{(kind === 'OPEN' || kind === 'FOLLOW_UP' || kind === 'TREATMENT') && commonAttachments}{current && <WorkSection title="Lý do chỉnh sửa"><Field label="Lý do sửa *"><textarea className={inputCls} rows={3} maxLength={500} value={reason} onChange={(e) => setReason(e.target.value)} /></Field></WorkSection>}{error && <InlineMessage tone="err" title="Chưa thể lưu.">{error}</InlineMessage>}<div className="flex flex-wrap justify-end gap-2 border-t border-rule pt-4"><Button type="button" onClick={back}>Hủy</Button><Button variant="primary" type="submit">{current ? 'Lưu chỉnh sửa' : kind === 'TREATMENT' ? 'Lưu điều trị' : kind === 'FOLLOW_UP' ? 'Lưu theo dõi' : kind === 'STATUS' ? 'Lưu trạng thái' : 'Mở ca sức khỏe'}</Button></div></div></form></StateBoundary></Shell>
}
export function HealthPreviewScreen({ screen, role, state = 'success' }: { screen: ScreenDefinition; role?: ScreenRole; state?: ReviewState }) { if (screen.id === 'SCR-53') return <CaseList screen={screen} role={role} state={state} />; if (screen.id === 'SCR-54') return <Profile screen={screen} role={role} state={state} />; if (screen.id === 'SCR-55') return <RecordForm screen={screen} role={role} state={state} kind="OPEN" />; if (screen.id === 'SCR-56') return <RecordForm screen={screen} role={role} state={state} kind="FOLLOW_UP" />; if (screen.id === 'SCR-57') return <RecordForm screen={screen} role={role} state={state} kind="TREATMENT" />; return <RecordForm screen={screen} role={role} state={state} kind="STATUS" /> }
